struct DSU {
	vector<int> p;

	DSU(int n): p(n, -1) {}

	int find(int u) {
		return p[u] < 0 ? u : p[u] = find(p[u]);
	}

	bool conn(int u, int v) {
		return find(u) == find(v);
	}

	bool merge(int u, int v) {
		u = find(u);
		v = find(v);
		if(u == v) {
			return false;
		}
		if(p[u] < p[v]) {
			swap(u, v);
		}
		p[u] = v;
		return true;
	}

	void clear() {
		fill(begin(p), end(p), -1);
	}
};

void mst() {
	int n, m;
	cin >> n >> m;
	int deg[n];
	for(int i = 0; i < n; i++) {
		cin >> deg[i];
	}
	array<int, 4> edges[m];
	for(int i = 0; i < m; i++) {
		auto &[u, v, w, ii] = edges[i];
		cin >> u >> v >> w;
		u--;
		v--;
		ii = i + 1;
	}
	sort(edges, edges + m, [](const auto &a, const auto &b) -> bool {
		return a[2] > b[2];
	});
	DSU dsu(n);
	long ans = 0;
	vector<int> cans;
	for(auto &[u, v, w, i]: edges) {
		if(deg[u] && deg[v] && dsu.merge(u, v)) {
			deg[u]--;
			deg[v]--;
			ans += w;
			cans.push_back(i);
		}
	}
	assert(sz(cans) == n - 1);
	cout << ans << endl;
	for(auto &a: cans) {
		cout << a << endl;
	}
}

